--- math-tool.ps1 ---
[CmdletBinding()]
param(
    # Bound BigInteger growth so CLI requests remain deterministic and finite.
    # Keep this limit in sync with Get-Fibonacci's parameter validation and help.
    [ValidateRange(0, 10000)]
    [int] $N = 0
)

function Get-Fibonacci {
    <#
    .SYNOPSIS
    Returns the Fibonacci number for a non-negative integer.

    .PARAMETER N
    The non-negative integer position in the Fibonacci sequence, up to 10000.

    .OUTPUTS
    System.Numerics.BigInteger
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        # Bound BigInteger growth so CLI requests remain deterministic and finite.
        [ValidateRange(0, 10000)]
        [int] $N
    )

    if ($N -lt 2) {
        return [System.Numerics.BigInteger] $N
    }

    [System.Numerics.BigInteger] $previous = 0
    [System.Numerics.BigInteger] $current = 1

    for ($i = 2; $i -le $N; $i++) {
        [System.Numerics.BigInteger] $next = $previous + $current
        $previous = $current
        $current = $next
    }

    return $current
}

# Dot-sourced tests load the function without running the CLI output path.
$isDotSourced = $MyInvocation.InvocationName -eq '.'
if (-not $isDotSourced) {
    $value = Get-Fibonacci -N $N
    "Fibonacci($N) = $value"
}
--- math-tool.Tests.ps1 ---
BeforeAll {
    $script:MathToolPath = Join-Path $PSScriptRoot 'math-tool.ps1'
    $script:PowerShellPath = (Get-Command pwsh -ErrorAction Stop).Source
    . $script:MathToolPath
}

Describe 'Get-Fibonacci' {
    It 'returns 0 for N=0' {
        Get-Fibonacci -N 0 | Should -Be 0
    }

    It 'returns 1 for N=1' {
        Get-Fibonacci -N 1 | Should -Be 1
    }

    It 'returns 5 for N=5' {
        Get-Fibonacci -N 5 | Should -Be 5
    }

    It 'returns the exact BigInteger value for N=100' {
        Get-Fibonacci -N 100 | Should -Be ([System.Numerics.BigInteger]::Parse('354224848179261915075'))
    }

    It 'accepts the configured upper boundary' {
        Get-Fibonacci -N 10000 | Should -BeOfType ([System.Numerics.BigInteger])
    }

    It 'rejects negative N' {
        { Get-Fibonacci -N -1 } | Should -Throw
    }

    It 'rejects values above the configured range' {
        { Get-Fibonacci -N 10001 } | Should -Throw
    }
}

Describe 'math-tool loading' {
    It 'does not write a result line when dot-sourced' {
        $env:MATH_TOOL_TEST_PATH = $script:MathToolPath
        try {
            $global:LASTEXITCODE = $null
            $output = @(& $script:PowerShellPath -NoLogo -NoProfile -Command '. "$env:MATH_TOOL_TEST_PATH"')
        }
        finally {
            Remove-Item Env:\MATH_TOOL_TEST_PATH -ErrorAction SilentlyContinue
        }

        $LASTEXITCODE | Should -Be 0
        $output.Count | Should -Be 0
    }
}

Describe 'math-tool CLI' {
    It 'writes exactly one result line for N=<N>' -TestCases @(
        @{ N = 0; Expected = 'Fibonacci(0) = 0' }
        @{ N = 1; Expected = 'Fibonacci(1) = 1' }
        @{ N = 5; Expected = 'Fibonacci(5) = 5' }
    ) {
        param(
            [int] $N,
            [string] $Expected
        )

        $global:LASTEXITCODE = $null
        $output = @(& $script:PowerShellPath -NoLogo -NoProfile -File $script:MathToolPath -N $N)

        $LASTEXITCODE | Should -Be 0
        $output.Count | Should -Be 1
        $output[0] | Should -BeExactly $Expected
    }
}

